+                        @foreach (var reference in references)
+                        {
+                            <div class="review-entry">
+                                <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
+                                <p>@reference.Email | @reference.Phone</p>
+                            </div>
+                        }
+                    </div>
+                </div>
+
+                <!-- Cover Letter Review -->
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>Cover Letter</h3>
+                        <button class="btn-edit" @onclick="() => NavigateToStep(3)">Edit</button>
+                    </div>
+                    <div class="review-content">
+                        <p class="cover-letter-preview">@coverLetter</p>
+                    </div>
+                </div>
+
+                <div class="form-buttons">
+                    <button class="btn-back" @onclick="PreviousStep">Back</button>
+                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@isSubmitting">
+                        @if (isSubmitting)
+                        {
+                            <span>Submitting...</span>
+                        }
+                        else
+                        {
+                            <span>Submit Application</span>
+                        }
+                    </button>
+                </div>
+            }
+        </div>
+    }
+</div>
+
+@code {
+    private int currentStep = 0;
+    private readonly string[] stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+    private List<string> errors = new();
+
+    // Step 1: Personal Info
+    private string fullName = "";
+    private string email = "";
+    private string phone = "";
+    private string address = "";
+
+    // Step 2: Work History
+    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
+
+    // Step 3: References
+    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4: Cover Letter
+    private string coverLetter = "";
+
+    // Step 5: Submission
+    private bool isSubmitting = false;
+    private bool isSubmitted = false;
+    private int applicationId = 0;
+
+    private string GetStepClass(int stepIndex)
+    {
+        if (stepIndex == currentStep) return "active";
+        if (stepIndex < currentStep) return "completed";
+        return "future";
+    }
+
+    private void NavigateToStep(int step)
+    {
+        if (step < currentStep)
+        {
+            errors.Clear();
+            currentStep = step;
+        }
+    }
+
+    private async Task NextStep()
+    {
+        errors.Clear();
+
+        if (!await ValidateCurrentStep())
+            return;
+
+        currentStep++;
+    }
+
+    private void PreviousStep()
+    {
+        errors.Clear();
+        if (currentStep > 0)
+            currentStep--;
+    }
+
+    private async Task<bool> ValidateCurrentStep()
+    {
+        switch (currentStep)
+        {
+            case 0:
+                return await ValidatePersonalInfo();
+            case 1:
+                return ValidateWorkHistory();
+            case 2:
+                return ValidateReferences();
+            case 3:
+                return ValidateCoverLetter();
+            default:
+                return true;
+        }
+    }
+
+    private async Task<bool> ValidatePersonalInfo()
+    {
+        if (string.IsNullOrWhiteSpace(fullName))
+            errors.Add("Full name is required.");
+        if (string.IsNullOrWhiteSpace(email))
+            errors.Add("Email is required.");
+        if (string.IsNullOrWhiteSpace(phone))
+            errors.Add("Phone is required.");
+        if (string.IsNullOrWhiteSpace(address))
+            errors.Add("Address is required.");
+
+        if (errors.Count > 0)
+            return false;
+
+        var emailValid = await ApplicationService.ValidateEmailAsync(email);
+        if (!emailValid)
+        {
+            errors.Add("The email address is not valid.");
+            return false;
+        }
+
+        return true;
+    }
+
+    private bool ValidateWorkHistory()
+    {
+        for (int i = 0; i < workEntries.Count; i++)
+        {
+            var entry = workEntries[i];
+            if (string.IsNullOrWhiteSpace(entry.Company))
+                errors.Add($"Position {i + 1}: Company name is required.");
+            if (string.IsNullOrWhiteSpace(entry.Title))
+                errors.Add($"Position {i + 1}: Job title is required.");
+            if (entry.StartDate == default)
+                errors.Add($"Position {i + 1}: Start date is required.");
+        }
+        return errors.Count == 0;
+    }
+
+    private bool ValidateReferences()
+    {
+        for (int i = 0; i < references.Count; i++)
+        {
+            var r = references[i];
+            if (string.IsNullOrWhiteSpace(r.Name))
+                errors.Add($"Reference {i + 1}: Name is required.");
+            if (string.IsNullOrWhiteSpace(r.Relationship))
+                errors.Add($"Reference {i + 1}: Relationship is required.");
+            if (string.IsNullOrWhiteSpace(r.Email))
+                errors.Add($"Reference {i + 1}: Email is required.");
+            if (string.IsNullOrWhiteSpace(r.Phone))
+                errors.Add($"Reference {i + 1}: Phone is required.");
+        }
+        return errors.Count == 0;
+    }
+
+    private bool ValidateCoverLetter()
+    {
+        if (string.IsNullOrWhiteSpace(coverLetter))
+            errors.Add("Cover letter is required.");
+        return errors.Count == 0;
+    }
+
+    private void AddWorkEntry()
+    {
+        workEntries.Add(new WorkEntryModel());
+    }
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (workEntries.Count > 1)
+            workEntries.RemoveAt(index);
+    }
+
+    private void AddReference()
+    {
+        if (references.Count < 3)
+            references.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (references.Count > 2)
+            references.RemoveAt(index);
+    }
+
+    private async Task SubmitApplication()
+    {
+        isSubmitting = true;
+
+        var application = new JobApplication(
+            new PersonalInfo(fullName, email, phone, address),
+            new WorkHistory(workEntries.Select(e => new WorkEntry(
+                e.Company,
+                e.Title,
+                e.StartDate,
+                e.IsCurrent ? null : e.EndDate,
+                e.Description ?? ""
+            )).ToList()),
+            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
+            coverLetter
+        );
+
+        applicationId = await ApplicationService.SubmitApplicationAsync(application);
+        isSubmitted = true;
+        isSubmitting = false;
+    }
+
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = "";
+        public string Title { get; set; } = "";
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = "";
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = "";
+        public string Relationship { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+    }
